package com.example.examplemod.economy;
import com.example.examplemod.client.screen.InventoryBankLayout;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.*;
import java.util.*;
import static com.example.examplemod.economy.BankBook.*;
/** Uses the real economy and its real SavedData codec, not a second test-only money implementation. */
public final class BankCheck {
    private static int checks;private static void require(boolean v,String message){checks++;if(!v)throw new AssertionError(message);}
    private static void config()throws Exception{var f=com.example.examplemod.Config.class.getDeclaredField("SPEC");f.setAccessible(true);var spec=(net.neoforged.neoforge.common.ModConfigSpec)f.get(null);var data=com.electronwill.nightconfig.core.CommentedConfig.inMemory();spec.correct(data);data.set("items",List.of());var ctor=Class.forName("net.neoforged.fml.config.LoadedConfig").getDeclaredConstructors()[0];ctor.setAccessible(true);spec.acceptConfig((net.neoforged.fml.config.IConfigSpec.ILoadedConfig)ctor.newInstance(data,null,null));}
    private static EconomyManager reload(CompoundTag data)throws Exception{var method=EconomyManager.class.getDeclaredMethod("load",CompoundTag.class,HolderLookup.Provider.class);method.setAccessible(true);return(EconomyManager)method.invoke(null,data,null);}
    private static Command command(BankBook book,UUID who,Action action,UUID source,UUID destination,UUID peer,long amount,String note){return new Command(UUID.randomUUID(),book.revision(who),action,source,destination,peer,amount,0,note,0);}
    private static String run(BankBook b,UUID who,Action action,UUID source,UUID destination,UUID peer,long amount,String note){return b.execute(who,command(b,who,action,source,destination,peer,amount,note),1000000);}
    public static void main(String[] args)throws Exception{
        config();UUID a=UUID.randomUUID(),b=UUID.randomUUID(),outsider=UUID.randomUUID();var economy=new EconomyManager();economy.adminSetWallet(a,1000);var bank=economy.bank();var create=command(bank,a,Action.CREATE,null,null,null,0,"Locomotive");require(bank.execute(a,create,1000000).equals("ok"),"create account");UUID account=create.nonce();
        var deposit=command(bank,a,Action.TRANSFER,null,account,null,400,"");require(bank.execute(a,deposit,1000000).equals("ok")&&economy.wallet(a)==600&&bank.balance(a,account)==400,"internal transfer conserves CR and uses the existing wallet");require(bank.execute(a,deposit,1000001).equals("duplicate")&&economy.wallet(a)==600,"same nonce cannot debit twice");
        require(bank.execute(outsider,new Command(account,bank.revision(outsider),Action.CREATE,null,null,null,0,0,"Collision",0),1000000).equals("invalid")&&bank.balance(a,account)==400,"account id collision cannot replace another owner's funded account");
        require(run(bank,outsider,Action.TRANSFER,account,null,b,1,"").equals("permission")&&bank.balance(a,account)==400,"foreign source cannot be spent");
        require(run(bank,a,Action.CLOSE,account,null,null,0,"").equals("not_empty"),"funded account cannot be closed");
        require(run(bank,a,Action.TRANSFER,account,null,null,100,"").equals("ok")&&economy.wallet(a)==700&&bank.balance(a,account)==300,"withdrawal conserves CR");
        require(economy.pay(a,b,200)&&economy.wallet(a)==500&&economy.wallet(b)==200,"legacy pay uses existing money and new receipts");
        require(!economy.pay(a,b,-1)&&!economy.pay(a,a,1)&&!economy.pay(a,b,10000),"negative, self and unfunded payments rejected");
        var stale=command(bank,a,Action.TRANSFER,null,null,b,1,"");economy.pay(b,a,1);long before=economy.wallet(a);require(bank.execute(a,stale,1000000).equals("stale")&&economy.wallet(a)==before,"concurrent legacy wallet changes invalidate stale banking commands");
        var request=command(bank,b,Action.REQUEST,null,null,a,75,"Stone");require(bank.execute(b,request,1000000).equals("ok")&&economy.wallet(a)==before,"request does not debit or reserve payer money");
        require(run(bank,outsider,Action.PAY_REQUEST,null,request.nonce(),null,0,"").equals("permission"),"only named payer can approve request");
        var pay=command(bank,a,Action.PAY_REQUEST,account,request.nonce(),null,0,"");require(bank.execute(a,pay,1000001).equals("ok")&&bank.balance(a,account)==225,"request pays stored amount from chosen owned account");long received=economy.wallet(b);require(run(bank,a,Action.PAY_REQUEST,null,request.nonce(),null,0,"").equals("closed")&&economy.wallet(b)==received,"paid request cannot pay again with a new nonce");
        var root=economy.save(new CompoundTag(),null);economy=reload(root);bank=economy.bank();require(bank.balance(a,account)==225&&economy.wallet(b)==received&&bank.requests(a).stream().anyMatch(r->r.id().equals(request.nonce())&&r.state()==State.PAID),"balances and request settlement survive restart in the same economic save");require(bank.execute(a,pay,1000002).equals("duplicate")&&economy.wallet(b)==received,"retry remains idempotent after restart");
        var closed=command(bank,b,Action.REQUEST,null,null,a,5,"Test");bank.execute(b,closed,1000000);require(run(bank,a,Action.DECLINE,null,closed.nonce(),null,0,"").equals("ok")&&run(bank,a,Action.PAY_REQUEST,null,closed.nonce(),null,0,"").equals("closed"),"declined requests cannot be paid");
        var expired=command(bank,b,Action.REQUEST,null,null,a,5,"Expiry");bank.execute(b,expired,1000000);require(bank.execute(a,command(bank,a,Action.PAY_REQUEST,null,expired.nonce(),null,0,""),1000000+8L*86400000).equals("closed"),"expired request cannot debit");
        var legacy=root.copy();legacy.remove("PersonalBank");legacy.putInt("FormatVersion",8);var old=reload(legacy);require(old.wallet(a)==root.getList("Wallets",10).stream().map(t->(CompoundTag)t).filter(t->t.getUUID("Player").equals(a)).findFirst().orElseThrow().getLong("Amount")&&old.bank().accounts(a).isEmpty()&&old.bank().history(a).isEmpty(),"old wallets migrate as primary without invented history");
        var overflow=economy.save(new CompoundTag(),null);for(Tag raw:overflow.getList("Wallets",10)){var t=(CompoundTag)raw;if(t.getUUID("Player").equals(b))t.putLong("Amount",Long.MAX_VALUE);}var full=reload(overflow);long preserved=full.wallet(a);require(!full.pay(a,b,1)&&full.wallet(a)==preserved&&full.wallet(b)==Long.MAX_VALUE,"overflow rejected before debit");
        var corrupt=economy.save(new CompoundTag(),null);corrupt.getCompound("PersonalBank").getList("Accounts",10).getCompound(0).putLong("Balance",-1);boolean refused=false;try{reload(corrupt);}catch(java.lang.reflect.InvocationTargetException failure){refused=true;}require(refused,"corrupt funded bank data fails closed instead of deleting CR");
        for(int[] screen:new int[][]{{320,240},{426,240},{640,360},{960,540},{1920,1080}})for(boolean recipes:new boolean[]{false,true}){int left=(screen[0]-176)/2,top=(screen[1]-166)/2;var bounds=InventoryBankLayout.calculate(screen[0],screen[1],left,top,176,166,recipes);if(bounds!=null){require(bounds.x()>=0&&bounds.y()>=0&&bounds.x()+bounds.width()<=screen[0]&&bounds.y()+bounds.height()<=screen[1],"inventory finance widget fits viewport");require(bounds.x()+bounds.width()<=left||bounds.y()+bounds.height()<=top||bounds.y()>=top+166,"widget does not cover inventory slots");require(bounds.contains(bounds.x()+bounds.width()/2d,bounds.y()+bounds.height()/2d),"paint and click geometry match");if(recipes)require(bounds.compact(),"recipe book uses compact fallback");}}
        System.out.println("PASS: "+checks+" real-economy banking conservation, authorization, replay, migration and inventory geometry checks");
    }
}
